import { readFile, writeFile, mkdir, access } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { createHash } from "node:crypto";
import prettier from "prettier";
import { compactSchema } from "../apps/mcp-server/src/compact-schema.ts";

export const root = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
);
const marker =
  "Generated by scripts/generate-agent-docs.mjs. Edit docs/agent sources, not this output.";
const safe = (p) =>
  typeof p === "string" &&
  p.length > 0 &&
  p !== "." &&
  !p.includes("\0") &&
  path.posix.normalize(p) === p &&
  !path.posix.isAbsolute(p) &&
  !p.includes("\\") &&
  !p.split("/").includes("..") &&
  !p.includes(":");
export function validateRegistry(registry) {
  if (registry.format !== "analog-canvas-agent-distribution-v1")
    throw Error("Unknown distribution format");
  const ids = new Set(),
    uris = new Set(),
    kitPaths = new Set();
  for (const d of registry.documents) {
    if (ids.has(d.id)) throw Error(`Duplicate document: ${d.id}`);
    ids.add(d.id);
    if (!safe(d.source) || (d.kitPath && !safe(d.kitPath)))
      throw Error(`Unsafe path: ${d.id}`);
    if (
      !d.source.startsWith("docs/agent/") &&
      ![
        "packages/agent-adapter/src/agent-authoring-catalog.generated.ts",
        "fixtures/agent-api/agent-circuit-request.schema.json",
      ].includes(d.source)
    )
      throw Error(`Noncanonical source: ${d.source}`);
    if (
      !d.consumers.length ||
      d.consumers.some((c) => !registry.consumers.includes(c))
    )
      throw Error(`Unknown consumer: ${d.id}`);
    if (!d.task || !["entry", "required", "on-demand"].includes(d.load))
      throw Error(`Missing task/load: ${d.id}`);
    if (d.consumers.includes("http-kit") && !d.kitPath)
      throw Error(`Missing Kit destination: ${d.id}`);
    if (d.consumers.some((c) => c === "mcp" || c === "http-cli") && !d.uri)
      throw Error(`Missing resource destination: ${d.id}`);
    if (d.uri) {
      if (!d.uri.startsWith("analog-canvas://") || uris.has(d.uri))
        throw Error(`Duplicate/invalid URI: ${d.uri}`);
      uris.add(d.uri);
    }
    if (d.kitPath) {
      if (kitPaths.has(d.kitPath))
        throw Error(`Duplicate Kit path: ${d.kitPath}`);
      kitPaths.add(d.kitPath);
    }
  }
  const visited = new Set(),
    active = new Set();
  function visit(id) {
    if (!ids.has(id)) throw Error(`Missing dependency: ${id}`);
    if (active.has(id)) throw Error(`Required dependency cycle: ${id}`);
    if (visited.has(id)) return;
    active.add(id);
    const d = registry.documents.find((d) => d.id === id);
    for (const required of d.requires) {
      const target = registry.documents.find((d) => d.id === required);
      if (target && d.consumers.some((c) => !target.consumers.includes(c)))
        throw Error(`Dependency unavailable to consumer: ${id} -> ${required}`);
      visit(required);
    }
    active.delete(id);
    visited.add(id);
  }
  ids.forEach(visit);
  for (const p of Object.values(registry.templates))
    if (!safe(p) || !p.startsWith("docs/agent/"))
      throw Error(`Unsafe template: ${p}`);
  for (const key of Object.keys(registry.templates)) {
    const metadata = registry.templateConsumers[key];
    if (
      !metadata?.task ||
      !metadata.consumers.length ||
      metadata.consumers.some((c) => !registry.consumers.includes(c))
    )
      throw Error(`Missing template consumer/task: ${key}`);
  }
}

export async function compile(registry, repoRoot = root) {
  validateRegistry(registry);
  const outputs = new Map(),
    sourceTexts = new Map();
  async function read(p) {
    if (!sourceTexts.has(p))
      sourceTexts.set(
        p,
        (await readFile(path.join(repoRoot, p), "utf8")).replaceAll(
          "\r\n",
          "\n",
        ),
      );
    return sourceTexts.get(p);
  }
  const docs = new Map();
  for (const d of registry.documents) {
    let text = await read(d.source);
    if (d.kind === "catalog") {
      const { agentRazaviAuthoringCatalog } = await import(
        pathToFileURL(path.join(repoRoot, d.source)).href
      );
      text = JSON.stringify(agentRazaviAuthoringCatalog, null, 2) + "\n";
    }
    docs.set(d.id, text);
  }
  for (const d of registry.documents) {
    if (d.kind === "catalog") continue;
    for (const [, href] of docs.get(d.id).matchAll(/\]\(([^\s)]+)[^)]*\)/g)) {
      if (/^(?:[a-z][a-z\d+.-]*:|#)/i.test(href)) continue;
      const resolved = path.posix.normalize(
        path.posix.join(path.posix.dirname(d.source), href.split("#")[0]),
      );
      if (!safe(resolved)) throw Error(`Unsafe link in ${d.source}: ${href}`);
      await access(path.join(repoRoot, resolved)).catch(() => {
        throw Error(`Broken link in ${d.source}: ${href}`);
      });
    }
  }
  // Runtime guides must be self-contained in their versioned distribution.
  function project(d, surface) {
    // Compact the MCP projection at generation time, not on every resource read.
    // The canonical HTTP/Kit schema and runtime validators remain unchanged.
    if (surface === "mcp" && d.mimeType === "application/schema+json") {
      const original = docs.get(d.id);
      const compact = JSON.stringify(compactSchema(JSON.parse(original)));
      return compact.length < original.length ? compact : original;
    }
    return docs
      .get(d.id)
      .replace(/\]\(([^\s)]+)([^)]*)\)/g, (whole, href, suffix) => {
        if (/^(?:[a-z][a-z\d+.-]*:|#)/i.test(href)) return whole;
        const [file, anchor = ""] = href.split("#");
        const resolved = path.posix.normalize(
          path.posix.join(path.posix.dirname(d.source), file),
        );
        const target = registry.documents.find((x) => x.source === resolved);
        if (target && surface === "mcp" && target.uri)
          return `](${target.uri}${suffix})`;
        if (
          target &&
          surface === "kit" &&
          target.kitPath &&
          target.consumers.includes("http-kit")
        ) {
          let relative = path.posix.relative(
            path.posix.dirname(d.kitPath),
            target.kitPath,
          );
          return `](${relative}${anchor ? "#" + anchor : ""}${suffix})`;
        }
        throw Error(`Undistributed ${surface} link in ${d.source}: ${href}`);
      });
  }
  const resources = registry.documents
    .filter((d) => d.uri)
    .map((d) => ({
      uri: d.uri,
      name: d.name,
      description: d.description,
      mimeType: d.mimeType,
      text: project(d, "mcp"),
    }));
  const kit = registry.documents
    .filter((d) => d.kitPath && d.consumers.includes("http-kit"))
    .map((d) => ({ path: d.kitPath, content: project(d, "kit") }));
  const kitEntry = kit.find((file) => file.path === "README.md");
  if (!kitEntry) throw Error("Missing Kit entrypoint");
  kitEntry.content +=
    "\n## Task reading map\n\nLoad only the relevant task documents. This map is generated from the distribution registry.\n\n| Task | Load | Document |\n| --- | --- | --- |\n" +
    registry.documents
      .filter(
        (d) =>
          d.kitPath &&
          d.consumers.includes("http-kit") &&
          d.kitPath !== "README.md",
      )
      .map((d) => `| ${d.task} | ${d.load} | [${d.id}](${d.kitPath}) |`)
      .join("\n") +
    "\n";
  async function ts(p, body) {
    outputs.set(
      p,
      await prettier.format(`// ${marker}\n${body}`, {
        parser: "typescript",
        printWidth: 80,
      }),
    );
  }
  await ts(
    "apps/mcp-server/src/resources.generated.ts",
    `export interface McpResourceDocument {uri:string;name:string;description:string;mimeType:string;text:string}\nexport const mcpResources:readonly McpResourceDocument[]=${JSON.stringify(resources)};`,
  );
  await ts(
    "packages/agent-adapter/src/agent-docs.generated.ts",
    `export const agentKitVersion=${JSON.stringify(registry.kitVersion)};\nexport const agentKitFiles:readonly {path:string;content:string}[]=${JSON.stringify(kit)};`,
  );
  const help = JSON.parse(await read(registry.templates.toolHelp));
  await ts(
    "packages/agent-adapter/src/agent-api-help.generated.ts",
    `export const agentApiHelp=${JSON.stringify(JSON.parse(await read(registry.templates.apiHelp)))};`,
  );
  await ts(
    "apps/mcp-server/src/guidance.generated.ts",
    `export const agentToolHelp=${JSON.stringify(help)};\nexport const agentServerInstructions=${JSON.stringify((await read(registry.templates.instructions)).trim())};`,
  );
  const template = (await read(registry.templates.connect)).trimEnd();
  const placeholders = [...template.matchAll(/\{\{([^}]+)\}\}/g)].map(
    (m) => m[1],
  );
  if (
    placeholders.length !== 4 ||
    new Set(placeholders).size !== 4 ||
    placeholders.some(
      (x) => !["origin", "claim", "kitUrl", "manifestUrl"].includes(x),
    )
  )
    throw Error("Invalid connection placeholders");
  await ts(
    "apps/editor/src/agent/connection-guidance.generated.ts",
    `const template=${JSON.stringify(template)};\nexport function renderAgentConnectionInstructions(origin:string,claimCode:string):string {const values:Record<string,string>={origin,claim:JSON.stringify({claimCode}),kitUrl:origin+"/api/agent/kit",manifestUrl:origin+"/api/agent/mcp-manifest.json"}; return template.replace(/\\{\\{(origin|claim|kitUrl|manifestUrl)\\}\\}/g,(_,key:string)=>values[key]!);}`,
  );
  const skill = await read(registry.templates.skill);
  outputs.set(
    "skills/circuit-layout/SKILL.md",
    skill.replace(/^(---\n[\s\S]*?\n---\n)/, `$1\n<!-- ${marker} -->\n`),
  );
  outputs.set(
    "skills/circuit-layout/agents/openai.yaml",
    `# ${marker}\n${await read(registry.templates.skillMetadata)}`,
  );
  outputs.set(
    "skills/circuit-layout/references/manifest.md",
    `<!-- ${marker} -->\n# Circuit task reading map\n\nSelect your transport first. Read only the task-relevant rows; reading is not a permission gate.\n\n| Task | Load | Source |\n| --- | --- | --- |\n` +
      registry.documents
        .filter(
          (d) => d.consumers.includes("repo-skill") && d.kind !== "catalog",
        )
        .map(
          (d) => `| ${d.task} | ${d.load} | [${d.id}](../../../${d.source}) |`,
        )
        .join("\n") +
      "\n",
  );
  const inputs = {
    "packages/agent-adapter/src/agent-api-help.generated.ts": [
      registry.templates.apiHelp,
    ],
    "apps/mcp-server/src/resources.generated.ts": registry.documents
      .filter((d) => d.uri)
      .map((d) => d.source),
    "packages/agent-adapter/src/agent-docs.generated.ts": registry.documents
      .filter((d) => d.kitPath && d.consumers.includes("http-kit"))
      .map((d) => d.source),
    "apps/mcp-server/src/guidance.generated.ts": [
      registry.templates.instructions,
      registry.templates.toolHelp,
    ],
    "apps/editor/src/agent/connection-guidance.generated.ts": [
      registry.templates.connect,
    ],
    "skills/circuit-layout/SKILL.md": [registry.templates.skill],
    "skills/circuit-layout/agents/openai.yaml": [
      registry.templates.skillMetadata,
    ],
    "skills/circuit-layout/references/manifest.md": [],
  };
  const report = {
    format: registry.format,
    version: registry.version,
    registrySha256: createHash("sha256")
      .update(JSON.stringify(registry))
      .digest("hex"),
    sources: [...sourceTexts].map(([source, text]) => ({
      source,
      sha256: createHash("sha256").update(text).digest("hex"),
    })),
    documents: registry.documents.map((d) => ({
      id: d.id,
      source: d.source,
      consumers: d.consumers,
      task: d.task,
      load: d.load,
      requires: d.requires,
      uri: d.uri,
      kitPath: d.kitPath,
    })),
    templates: registry.templateConsumers,
    outputs: [...outputs].map(([file, text]) => ({
      file,
      sources: ["docs/agent/distribution.json", ...inputs[file]],
      sha256: createHash("sha256").update(text).digest("hex"),
    })),
  };
  outputs.set(
    "docs/agent/distribution.generated.json",
    JSON.stringify(report, null, 2) + "\n",
  );
  return outputs;
}
export async function writeOutputs(outputs, repoRoot, check) {
  const stale = [];
  for (const [file, text] of outputs) {
    if (
      (await readFile(path.join(repoRoot, file), "utf8").catch(() => null)) ===
      text
    )
      continue;
    stale.push(file);
    if (!check) {
      await mkdir(path.dirname(path.join(repoRoot, file)), { recursive: true });
      await writeFile(path.join(repoRoot, file), text);
    }
  }
  if (check && stale.length)
    throw Error(
      `Stale Agent documentation; run pnpm agent-docs:generate:\n${stale.join("\n")}`,
    );
  return stale;
}
export async function run(check = false) {
  const registry = JSON.parse(
    await readFile(path.join(root, "docs/agent/distribution.json"), "utf8"),
  );
  const outputs = await compile(registry);
  const stale = await writeOutputs(outputs, root, check);
  console.log(
    `Agent documentation: ${outputs.size} outputs, ${stale.length} ${check ? "stale" : "updated"}`,
  );
}
if (
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
)
  await run(process.argv.includes("--check"));
